import json, re, sys
from pathlib import Path
import pyarrow.parquet as pq
sys.path.insert(0, "/workspace/qat/vendor/verl")
from verl.utils.reward_score.math_reward import compute_score as math_score, is_equiv, last_boxed_only_string, remove_boxed

table = pq.read_table("/workspace/data/skywork_or1_7b_math_difficulty1-15_16k.parquet", columns=["prompt","reward_model"])
rows = table.to_pylist()

def normq(s):
    return re.sub(r"\s+", " ", s).strip()
def prompt_text(p):
    return "\n".join(m.get("content","") for m in p)
gt = {normq(prompt_text(r["prompt"])): json.loads(r["reward_model"]["ground_truth"]) for r in rows}

# distribution of gt forms
kinds={"int":0,"frac":0,"other":0,"multi":0}
for answers in gt.values():
    if len(answers)>1: kinds["multi"]+=1
    a=answers[0]
    if re.fullmatch(r"-?\d+", a.strip()): kinds["int"]+=1
    elif "frac" in a or "/" in a: kinds["frac"]+=1
    else: kinds["other"]+=1
print("gt kinds", kinds, "n", len(gt))

files = sorted(Path("/workspace/evidence/training").rglob("*.jsonl"))

def grade(output, answers):
    # any answer matches via math_reward
    for a in answers:
        if math_score(output, a) == 1.0:
            return True
    return False

# also: last boxed normalized equality after is_equiv individually already in grade

print("\nfile  recorded  math_reward_any  only_math_not_recorded")
total_extra=[]
for f in files:
    recs=[json.loads(l) for l in f.open()]
    rec=math=0
    extras=[]
    for r in recs:
        m=re.search(r"<｜User｜>(.*?)<｜Assistant｜>", r["input"], re.S)
        answers=gt[normq(m.group(1))]
        ok=grade(r["output"], answers)
        rec += int(r["score"]>0)
        math += int(ok)
        if ok and r["score"]<=0:
            boxed=last_boxed_only_string(r["output"])
            try:
                pred=remove_boxed(boxed) if boxed else None
            except Exception:
                pred=None
            extras.append((pred, answers))
    print(f"{f.name} rec={rec} math={math} extra={len(extras)}")
    for e in extras[:8]:
        print("   ", e)
